sys_script_email.script:
(function runMailScript( /* GlideRecord */ current, /* TemplatePrinter */ template,
    /* Optional EmailOutbound */
    email, /* Optional GlideRecord */ email_action,
    /* Optional GlideRecord */
    event) {
    //var url = gs.getProperty("glide.servlet.uri") + "services?id=hoc_hrm_todos_page&amp;table=sn_hr_core_task&amp;sys_id=" + current.sys_id;

    var url = ""; 

    if (current.parent.hr_service.getDisplayValue() == "Disability Management") {
        url = gs.getProperty('glide.servlet.uri') + 'services?id=hrm_todos_page&parent_case_number=' + current.parent.number;

    } else {

    url = gs.getProperty('glide.servlet.uri') + 'services/?id=hrm_todo&sysparm_tableName=sn_hr_core_task&sys_id=' + current.sys_id;

    var hasHR = new GlideAggregate('sys_user_has_role');
	var count = 0;

    hasHR.addAggregate('COUNT');
    hasHR.addQuery('user', current.assigned_to.toString());
    hasHR.addQuery('role.name', 'sn_hr_core.case_writer');
    hasHR.query();


	if (hasHR.next()) {

    	count = hasHR.getAggregate('COUNT');

	}

    if (count > 0) {
        url = gs.getProperty('glide.servlet.uri') + 'now/hr/agent/record/' + current.getTableName() + '/' + current.sys_id;
    }

	}
    //var url = gs.getProperty('glide.servlet.uri') + '/now/hr/agent/record/'+ current.getTableName() + '/' + current.sys_id;
    //url = url + "&amp;lang=en";
    var label = "Open the record";

    template.print("<a href=" + url + "><button>" + label + "</button></a>");

})(current, template, email, email_action, event);
